"net-worth":{label:"Net-worth snapshots",fields:[["date","Valuation date","date"],["assets","Total assets (₹)","number"],["liabilities","Total liabilities (₹)","number"],["notes","Notes","text"]]},
insights:{label:"Insights & actions",fields:[["title","Observation","text"],["action","Suggested action","text"],["status","Status","select",["Open","Reviewed","Done"]],["date","Date","date"]]},
calculators:{label:"Calculator history",fields:[["name","Calculation","text"],["principal","Principal / monthly amount (₹)","number"],["rate","Annual rate (%)","number"],["years","Years","number"],["result","Estimated result (₹)","number"]]},
"tax-estimator":{label:"Tax planning worksheet",fields:[["financialYear","Financial year","select",["2026–27","2025–26"]],["regime","Regime","select",["New","Old"]],["income","Annual income (₹)","number"],["deductions","Deductions entered (₹)","number"],["notes","Notes","text"]]},
